import React, { useState } from "react";
import WorkerSplash from "./components/WorkerSplash";

function App() {
  const [showSplash, setShowSplash] = useState(true);

  return (
    <div className="App">
      {showSplash ? (
        <WorkerSplash onComplete={() => setShowSplash(false)} />
      ) : (
        <div className="h-screen flex items-center justify-center bg-[#FDFAD8]">
           <h1 className="text-6xl font-black uppercase italic text-[#47510B] tracking-tighter">
             System_Online
           </h1>
        </div>
      )}
    </div>
  );
}

export default App;
